def scheduler_create_job(name, schedule, command, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0100000" if __import__("os").path.isdir("./environment_mix/0100000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validate
    if not isinstance(name, str):
        resp = _err("VALIDATION_ERROR", "name must be a string", field="name")
    elif not isinstance(schedule, str):
        resp = _err("VALIDATION_ERROR", "schedule must be a string", field="schedule")
    elif not isinstance(command, str):
        resp = _err("VALIDATION_ERROR", "command must be a string", field="command")
    else:
        resp = None

    if resp is not None:
        _audit = _load("audit_log.json")
        if not isinstance(_audit, list):
            _audit = []
        _audit.append({
            "ts": datetime.datetime.utcnow().isoformat() + "Z",
            "endpoint": "scheduler_create_job",
            "status": "error",
            "error_code": resp["error"]["code"],
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("audit_log.json", _audit)
        return resp

    jobs = _load("jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    # Generate unique job id
    existing_ids = {j.get("job_id") for j in jobs if isinstance(j, dict)}
    def _new_id():
        # job-<UTC yyyymmddHHMMSS>-<4digits>
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
        return f"job-{ts}-{random.randint(0, 9999):04d}"

    job_id = _new_id()
    tries = 0
    while job_id in existing_ids and tries < 20:
        job_id = _new_id()
        tries += 1
    if job_id in existing_ids:
        resp = _err("CONFLICT", "Unable to allocate unique job_id")
        _audit = _load("audit_log.json")
        if not isinstance(_audit, list):
            _audit = []
        _audit.append({
            "ts": datetime.datetime.utcnow().isoformat() + "Z",
            "endpoint": "scheduler_create_job",
            "status": "error",
            "error_code": resp["error"]["code"],
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("audit_log.json", _audit)
        return resp

    job = {
        "job_id": job_id,
        "name": name,
        "schedule": schedule,
        "enabled": True,
        "command": command,
    }

    jobs.append(job)
    _save("jobs.json", jobs)

    resp = {"data": job}

    _audit = _load("audit_log.json")
    if not isinstance(_audit, list):
        _audit = []
    _audit.append({
        "ts": datetime.datetime.utcnow().isoformat() + "Z",
        "endpoint": "scheduler_create_job",
        "status": "ok",
        "latency_ms": int((time.time() - t0) * 1000),
        "job_id": job_id,
    })
    _save("audit_log.json", _audit)

    return resp

def scheduler_update_job(job_id, schedule=None, enabled=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0100000" if __import__("os").path.isdir("./environment_mix/0100000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validate
    if not isinstance(job_id, str):
        resp = _err("VALIDATION_ERROR", "job_id must be a string", field="job_id")
    elif schedule is not None and not isinstance(schedule, str):
        resp = _err("VALIDATION_ERROR", "schedule must be a string when provided", field="schedule")
    elif enabled is not None and not isinstance(enabled, bool):
        resp = _err("VALIDATION_ERROR", "enabled must be a boolean when provided", field="enabled")
    elif schedule is None and enabled is None:
        resp = _err("VALIDATION_ERROR", "At least one of schedule or enabled must be provided")
    else:
        resp = None

    if resp is not None:
        _audit = _load("audit_log.json")
        if not isinstance(_audit, list):
            _audit = []
        _audit.append({
            "ts": datetime.datetime.utcnow().isoformat() + "Z",
            "endpoint": "scheduler_update_job",
            "status": "error",
            "error_code": resp["error"]["code"],
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("audit_log.json", _audit)
        return resp

    jobs = _load("jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    idx = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("job_id") == job_id:
            idx = i
            break

    if idx is None:
        resp = _err("NOT_FOUND", "Job not found", job_id=job_id)
        _audit = _load("audit_log.json")
        if not isinstance(_audit, list):
            _audit = []
        _audit.append({
            "ts": datetime.datetime.utcnow().isoformat() + "Z",
            "endpoint": "scheduler_update_job",
            "status": "error",
            "error_code": resp["error"]["code"],
            "latency_ms": int((time.time() - t0) * 1000),
            "job_id": job_id,
        })
        _save("audit_log.json", _audit)
        return resp

    # Apply updates
    job = dict(jobs[idx])
    if schedule is not None:
        job["schedule"] = schedule
    if enabled is not None:
        job["enabled"] = enabled

    jobs[idx] = job
    _save("jobs.json", jobs)

    resp = {"data": job}

    _audit = _load("audit_log.json")
    if not isinstance(_audit, list):
        _audit = []
    _audit.append({
        "ts": datetime.datetime.utcnow().isoformat() + "Z",
        "endpoint": "scheduler_update_job",
        "status": "ok",
        "latency_ms": int((time.time() - t0) * 1000),
        "job_id": job_id,
    })
    _save("audit_log.json", _audit)

    return resp

