def scheduler_job_history(job_id=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0100000" if __import__("os").path.isdir("./environment_mix/0100000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validate
    if job_id is not None and not isinstance(job_id, str):
        resp = _err("VALIDATION_ERROR", "job_id must be a string when provided", field="job_id")
        _audit = _load("audit_log.json")
        if not isinstance(_audit, list):
            _audit = []
        _audit.append({
            "ts": datetime.datetime.utcnow().isoformat() + "Z",
            "endpoint": "scheduler_job_history",
            "status": "error",
            "error_code": resp["error"]["code"],
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("audit_log.json", _audit)
        return resp

    jobs = _load("jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    job_ids = {j.get("job_id") for j in jobs if isinstance(j, dict)}

    if job_id is not None and job_id not in job_ids:
        resp = _err("NOT_FOUND", "Job not found", job_id=job_id)
        _audit = _load("audit_log.json")
        if not isinstance(_audit, list):
            _audit = []
        _audit.append({
            "ts": datetime.datetime.utcnow().isoformat() + "Z",
            "endpoint": "scheduler_job_history",
            "status": "error",
            "error_code": resp["error"]["code"],
            "latency_ms": int((time.time() - t0) * 1000),
            "job_id": job_id,
        })
        _save("audit_log.json", _audit)
        return resp

    hist = _load("job_histories.json")
    if not isinstance(hist, list):
        hist = []

    rows = hist
    if job_id is not None:
        rows = [h for h in hist if isinstance(h, dict) and h.get("job_id") == job_id]

    # Sort: newest first when possible
    def _ts_key(r):
        s = r.get("started_at")
        if not isinstance(s, str):
            return ""
        return s
    rows = sorted(rows, key=_ts_key, reverse=True)

    resp = {
        "data": rows,
        "meta": {
            "total": len(rows),
            "job_id": job_id,
        },
    }

    _audit = _load("audit_log.json")
    if not isinstance(_audit, list):
        _audit = []
    _audit.append({
        "ts": datetime.datetime.utcnow().isoformat() + "Z",
        "endpoint": "scheduler_job_history",
        "status": "ok",
        "latency_ms": int((time.time() - t0) * 1000),
        "result_count": len(rows),
        "job_id": job_id,
    })
    _save("audit_log.json", _audit)

    return resp
